from paging import between_inclusive

def test_between_adjacent():
    assert between_inclusive([0, 1, 2], 1, 2) == [1, 2]

def test_between_same():
    assert between_inclusive([0, 1, 2], 1, 1) == [1]

def test_between_reverse():
